import{_ as a,c as r,o,a7 as t}from"./chunks/framework.Cx0hAcWL.js";const n=JSON.parse('{"title":"组件&桌面黑屏解决方法","description":"祝各位永远不砖。","frontmatter":{"top":2,"sticky":99,"description":"祝各位永远不砖。","tag":["酷安"],"recommend":2},"headers":[],"relativePath":"coolapk/recover.md","filePath":"coolapk/recover.md"}'),c={name:"coolapk/recover.md"};function i(p,e,s,m,d,l){return o(),r("div",{"data-pagefind-body":!0},e[0]||(e[0]=[t('<h1 id="组件-桌面黑屏解决方法" tabindex="-1">组件&amp;桌面黑屏解决方法 <a class="header-anchor" href="#组件-桌面黑屏解决方法" aria-label="Permalink to “组件&amp;桌面黑屏解决方法”">​</a></h1><details class="details custom-block"><summary>本文酷安链接</summary><p><a href="https://www.coolapk.com/feed/60370049?shareKey=MzVhMTFmODdiM2FmNjgwZTY0OTY~&amp;shareUid=22430622&amp;shareFrom=com.coolapk.market_13.4.1" target="_blank" rel="noreferrer">https://www.coolapk.com/feed/60370049?shareKey=MzVhMTFmODdiM2FmNjgwZTY0OTY~&amp;shareUid=22430622&amp;shareFrom=com.coolapk.market_13.4.1</a></p></details><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>⚠️首先，养成良好的玩机习惯，安装前一定要备份原本的APK，方便后续黑屏了可以直接还原！！！</p><p>备份可以用 <a href="https://mt2.cn/" target="_blank" rel="noreferrer">MT管理器</a>，侧边栏里 <strong>安装包提取</strong> 功能。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>酷安@Enmmmmmm 收集了各个系统的原版界面组件：</p><p><a href="https://www.123pan.com/s/LN30Vv-3xqPh" target="_blank" rel="noreferrer">https://www.123pan.com/s/LN30Vv-3xqPh</a></p><p>我这里也准备了几个官方组件和桌面，万一用的上：</p><p><a href="https://www.123pan.com/s/Kb4vjv-gF4Jh" target="_blank" rel="noreferrer">https://www.123pan.com/s/Kb4vjv-gF4Jh</a></p><p>组件和桌面不区分设备型号，同系统版本通用。</p></div><p>如果黑屏了，我们分多种情况考虑：</p><h2 id="桌面黑屏-com-miui-home" tabindex="-1">桌面黑屏（com.miui.home） <a class="header-anchor" href="#桌面黑屏-com-miui-home" aria-label="Permalink to “桌面黑屏（com.miui.home）”">​</a></h2><h3 id="方法a" tabindex="-1">方法A <a class="header-anchor" href="#方法a" aria-label="Permalink to “方法A”">​</a></h3><p>桌面黑屏一般是可以解锁锁屏界面的，我们直接通过 <code>控制中心</code> 或者 <code>呼出小爱</code>，打开MT管理器。直接装回原来备份的官方桌面。</p><h3 id="方法b-不太推荐" tabindex="-1">方法B（不太推荐） <a class="header-anchor" href="#方法b-不太推荐" aria-label="Permalink to “方法B（不太推荐）”">​</a></h3><p>打开MT管理器 <code>安装包提取</code> 功能，搜索找到系统桌面，左下角 <code>更多</code> → <code>详情</code>，在跳转的页面选择 <code>卸载更新</code>。这种方法<strong>会还原桌面的布局</strong>，故不推荐。</p><h2 id="控制中心组件黑屏-miui-systemui-plugin" tabindex="-1">控制中心组件黑屏（miui.systemui.plugin） <a class="header-anchor" href="#控制中心组件黑屏-miui-systemui-plugin" aria-label="Permalink to “控制中心组件黑屏（miui.systemui.plugin）”">​</a></h2><h3 id="情况a-能解锁进桌面-只是控制中心拉不下来。" tabindex="-1">情况A：能解锁进桌面，只是控制中心拉不下来。 <a class="header-anchor" href="#情况a-能解锁进桌面-只是控制中心拉不下来。" aria-label="Permalink to “情况A：能解锁进桌面，只是控制中心拉不下来。”">​</a></h3><p>打开MT管理器，直接装回原来备份的官方控制中心。<br>也可以通过“卸载更新”解决，但是也会还原控制中心的布局，故不推荐。</p><h3 id="⭐情况b-卡锁屏界面-黑屏、闪屏。" tabindex="-1">⭐情况B：卡锁屏界面，黑屏、闪屏。 <a class="header-anchor" href="#⭐情况b-卡锁屏界面-黑屏、闪屏。" aria-label="Permalink to “⭐情况B：卡锁屏界面，黑屏、闪屏。”">​</a></h3><p>重启至TWRP，打开 <code>高级</code> → <code>文件管理</code>，打开路径 <code>data</code> → <code>app</code>，然后 <code>按日期倒序排序</code>，打开最新的文件夹，确定里面是 <code>miui.systemui.plugin-xxx</code> 文件夹，打开，然后删掉里面的base.apk，重启即可。</p><p>（TWRP下载见 <a href="https://www.123pan.com/s/qHhDVv-nuQJv" target="_blank" rel="noreferrer">@mi_block</a> ，刷入方法自行搜索）</p><hr><p>引流关键词：黑屏 闪屏 跳屏 卡死 打不开 进不去 控制中心 二改 修改版 核心</p><p>#HyperOS# #MIUI系统界面组件# #MIUI系统桌面#</p>',21)]))}const b=a(c,[["render",i]]);export{n as __pageData,b as default};
